package app.monstera.sample.presentation

/*
 * Presentation logic shared by the shell: screen layout, clipping, effects and texts.
 *
 * Boundaries (contract section 9):
 *  - It reads simulation output (score, lives, entity boxes) and writes nothing back.
 *  - It never reads the clock; the shell passes the frame time to advance().
 *  - It has no Android or Compose imports, so it runs in plain JVM unit tests.
 *  - Floating point is allowed here because nothing in this file can reach the simulation.
 */

/** Axis-aligned box. World units or screen pixels, as documented where it is used. */
data class Box(val x: Float, val y: Float, val w: Float, val h: Float) {
    val right: Float get() = x + w
    val bottom: Float get() = y + h

    /** The overlap of two boxes, or null when they only touch or are apart. */
    fun intersect(other: Box): Box? {
        val l = maxOf(x, other.x)
        val t = maxOf(y, other.y)
        val r = minOf(right, other.right)
        val b = minOf(bottom, other.bottom)
        return if (r > l && b > t) Box(l, t, r - l, b - t) else null
    }

    /** True when [other] lies completely inside this box (edges may touch). */
    fun contains(other: Box): Boolean =
        other.x >= x && other.y >= y && other.right <= right && other.bottom <= bottom
}

/**
 * Screen layout: a HUD bar across the top (below [insetTop], the status bar or notch inset) and the world
 * rectangle fitted into the rest (above [insetBottom], the gesture or navigation bar), centred and with the world's aspect ratio. Everything else on screen is
 * letterbox, filled with the background colour.
 */
class Layout(val viewW: Float, val viewH: Float, val worldW: Float, val worldH: Float, val insetTop: Float = 0f, val insetBottom: Float = 0f) {
    val hudHeight: Float = minOf(maxOf(HUD_MIN, minOf(viewW, viewH) * HUD_FRACTION), viewH * HUD_MAX_FRACTION)
    val hud: Box = Box(0f, insetTop, viewW, hudHeight)

    /** Screen pixels per world unit (0 when the view or the world has no area). */
    val scale: Float

    /** The world rectangle in screen pixels. Drawing is clipped to it. */
    val world: Box

    init {
        val top = insetTop + hudHeight
        val availH = viewH - top - insetBottom
        scale = if (worldW <= 0f || worldH <= 0f || viewW <= 0f || availH <= 0f) 0f
        else minOf(viewW / worldW, availH / worldH)
        val w = worldW * scale
        val h = worldH * scale
        world = Box((viewW - w) / 2f, top + (availH - h) / 2f, w, h)
    }

    /** A box given in world units, in screen pixels. */
    fun toScreen(box: Box): Box = Box(world.x + box.x * scale, world.y + box.y * scale, box.w * scale, box.h * scale)

    /** The part of a world-unit box that is visible inside the world rectangle, in pixels, or null. */
    fun visible(box: Box): Box? = toScreen(box).intersect(world)

    companion object {
        const val HUD_MIN = 40f
        const val HUD_FRACTION = 0.09f
        const val HUD_MAX_FRACTION = 0.25f
    }
}

enum class Effect { NONE, BURST, PICKUP }

/** One entity as seen at the end of a frame; the box is in world units. */
data class Tracked(val id: Long, val kind: Int, val box: Box)

class Particle(var x: Float, var y: Float, val vx: Float, val vy: Float, val size: Float, val kind: Int) {
    var age: Float = 0f
    val alpha: Float get() = 1f - age / EffectTracker.PARTICLE_SECONDS
}

class Ring(val x: Float, val y: Float, val maxRadius: Float, val kind: Int) {
    var age: Float = 0f
    val radius: Float get() = maxRadius * age / EffectTracker.RING_SECONDS
    val alpha: Float get() = 1f - age / EffectTracker.RING_SECONDS
}

class Popup(val text: String, val x: Float, var y: Float) {
    var age: Float = 0f
    val alpha: Float get() = 1f - age / EffectTracker.POPUP_SECONDS
}

/**
 * Derives effects from what changed between two frames, never from the simulation internals:
 *  - an entity of an effect kind that disappears while its last box was completely inside the world
 *    bursts (particles) or pops (ring, plus "+N" when the score rose in the same frame);
 *  - lives going down flashes the world and shakes it briefly.
 * Entities that expire or leave the world by their own motion are never completely inside when they
 * vanish, so they cause no effect. Use effect NONE for kinds that could still do so.
 */
class EffectTracker(private val effects: List<Effect>, private val world: Box) {
    private var previous: Map<Long, Tracked> = emptyMap()
    private var lastScore: Long? = null
    private var lastLives: Long? = null
    private var shakeAge: Float = SHAKE_SECONDS

    val particles = ArrayList<Particle>()
    val rings = ArrayList<Ring>()
    val popups = ArrayList<Popup>()

    /** 1 right after a life is lost, falling to 0. */
    var flash: Float = 0f
        private set

    /** Call once per rendered frame with the state after the frame's ticks. */
    fun observe(score: Long, lives: Long, entities: List<Tracked>) {
        val now = LinkedHashMap<Long, Tracked>()
        for (e in entities) now[e.id] = e
        val scoreDelta = lastScore?.let { score - it } ?: 0L
        var popupDone = false
        for ((id, gone) in previous) {
            if (id in now) continue
            val effect = effects.getOrElse(gone.kind) { Effect.NONE }
            if (effect == Effect.NONE || !world.contains(gone.box)) continue
            val cx = gone.box.x + gone.box.w / 2f
            val cy = gone.box.y + gone.box.h / 2f
            val reach = maxOf(gone.box.w, gone.box.h)
            if (effect == Effect.BURST) {
                for ((dx, dy) in DIRECTIONS) {
                    if (particles.size < MAX_PARTICLES) {
                        particles.add(Particle(cx, cy, dx * reach * 2f, dy * reach * 2f, maxOf(4f, reach * 0.12f), gone.kind))
                    }
                }
            } else if (rings.size < MAX_RINGS) {
                rings.add(Ring(cx, cy, reach, gone.kind))
            }
            if (!popupDone && scoreDelta > 0L && popups.size < MAX_POPUPS) {
                popups.add(Popup("+$scoreDelta", cx, cy))
                popupDone = true
            }
        }
        val before = lastLives
        if (before != null && lives < before) {
            flash = 1f
            shakeAge = 0f
        }
        previous = now
        lastScore = score
        lastLives = lives
    }

    /** Moves time forward by the frame time in seconds (display time, not simulation time). */
    fun advance(dt: Float) {
        if (dt <= 0f) return
        for (p in particles) { p.x += p.vx * dt; p.y += p.vy * dt; p.age += dt }
        for (r in rings) r.age += dt
        for (p in popups) { p.age += dt; p.y -= POPUP_RISE * dt }
        particles.removeAll { it.age >= PARTICLE_SECONDS }
        rings.removeAll { it.age >= RING_SECONDS }
        popups.removeAll { it.age >= POPUP_SECONDS }
        flash = maxOf(0f, flash - dt / FLASH_SECONDS)
        shakeAge += dt
    }

    /** Horizontal shake offset in world units; alternates sign every 1/60 s and fades out. */
    fun shakeX(): Float = if (shakeAge >= SHAKE_SECONDS) 0f else SHAKE_UNITS * (1f - shakeAge / SHAKE_SECONDS) * sign()

    fun shakeY(): Float = shakeX() * -0.5f

    private fun sign(): Float = if ((shakeAge * 60f).toInt() % 2 == 0) 1f else -1f

    fun reset() {
        previous = emptyMap()
        lastScore = null
        lastLives = null
        particles.clear(); rings.clear(); popups.clear()
        flash = 0f
        shakeAge = SHAKE_SECONDS
    }

    companion object {
        const val PARTICLE_SECONDS = 0.4f
        const val RING_SECONDS = 0.3f
        const val POPUP_SECONDS = 0.6f
        const val FLASH_SECONDS = 0.25f
        const val SHAKE_SECONDS = 0.15f
        const val SHAKE_UNITS = 12f
        const val POPUP_RISE = 60f
        const val MAX_PARTICLES = 96
        const val MAX_RINGS = 16
        const val MAX_POPUPS = 8

        private const val D = 0.70710677f
        private val DIRECTIONS = listOf(
            1f to 0f, D to D, 0f to 1f, -D to D, -1f to 0f, -D to -D, 0f to -1f, D to -D,
        )
    }
}

/** HUD, card and glyph texts. */
object Texts {
    const val MAX_LIFE_GLYPHS = 8

    /** One [glyph] per life, "+n" when more than [MAX_LIFE_GLYPHS]; the empty glyph shows the number as text. */
    fun lives(glyph: String, lives: Long): String {
        val n = maxOf(0L, lives)
        if (glyph.isEmpty()) return "lives $n"
        val shown = minOf(n, MAX_LIFE_GLYPHS.toLong()).toInt()
        val extra = if (n > MAX_LIFE_GLYPHS) " +${n - MAX_LIFE_GLYPHS}" else ""
        return glyph.repeat(shown) + extra
    }

    fun score(label: String, score: Long): String = "$label $score"

    /** The end card is a win when the game ended with lives left. */
    fun endTitle(lives: Long, winTitle: String, loseTitle: String): String = if (lives > 0L) winTitle else loseTitle

    /** Edge length of the square a glyph is drawn in: a little smaller than the shorter side of its box. */
    fun glyphSize(box: Box): Float = minOf(box.w, box.h) * 0.9f
}
